mapper.select:
SELECT t.id, t.name, COUNT(*) AS media_count FROM media m INNER JOIN location l ON l.id = m.location_id AND l.status = 1 INNER JOIN campus c ON c.id = l.campus_id AND c.status = 1 INNER JOIN city ci ON ci.id = c.city_id AND ci.status = 1 INNER JOIN media_tag mt ON mt.media_id = m.id INNER JOIN tag t ON t.id = mt.tag_id WHERE m.status = 1
AND ci.id = #{cityId}
GROUP BY t.id, t.name ORDER BY media_count DESC, t.name, t.id LIMIT #{tagLimit}
